-- supabase/seed.sql
-- 40 clearly labelled DEMO listings (PROJECT_SPEC.md section 6).
-- Every row has is_demo = true and a slug starting with `demo-`. All
-- organizations are fictional and every URL points at example.org, so no real
-- deadline or detail is invented for a real organization.
--
-- The file is safe to run more than once: it first deletes its own demo rows.
-- Dates are relative to current_date, so the demo data never goes stale.
--
-- Load it automatically with `supabase db reset`, or paste it into the
-- Supabase SQL editor.

delete from public.opportunities where is_demo = true;
delete from public.organizations where name like 'Demo %';

