insert into public.opportunities (
  slug, organization_id, type, country, region, city, is_remote, is_hybrid, funding_type,
  funding_details, stipend_amount, currency, deadline_type, deadline_date, start_date,
  duration_months, education_levels, fields_of_study, nationality_rule, nationality_countries,
  uzbekistan_eligible, min_gpa, gpa_scale, age_min, age_max, language_requirements,
  required_documents, application_url, source_url, is_verified, last_verified_at, is_featured,
  is_demo, status, views_count, saves_count
)
select
  d.slug,
  o.id,
  d.type,
  d.country,
  d.region,
  d.city,
  d.is_remote,
  d.is_hybrid,
  d.funding_type,
  d.funding_details,
  d.stipend_amount,
  d.currency,
  d.deadline_type,
  case when d.deadline_type = 'fixed' then current_date + d.deadline_offset_days end,
  case when d.start_offset_days is not null then current_date + d.start_offset_days end,
  d.duration_months,
  d.education_levels,
  d.fields_of_study,
  d.nationality_rule,
  d.nationality_countries,
  d.uzbekistan_eligible,
  d.min_gpa,
  d.gpa_scale,
  d.age_min,
  d.age_max,
  d.language_requirements,
  d.required_documents,
  'https://example.org/demo/' || d.slug,
  'https://example.org/demo/' || d.slug,
  d.is_verified,
  case when d.is_verified then now() end,
  d.is_featured,
  true,
  'published',
  d.views_count,
  d.saves_count
from demo d
join public.organizations o on o.name = d.org;

-- ---------------------------------------------------------------------------
-- Translations: three locales for every demo listing. Content is intentionally
-- short but realistic; no real organization or deadline is described.
-- ---------------------------------------------------------------------------
with tr (slug, locale, title, short_summary, description_md, benefits, how_to_apply) as (
  values
  ('demo-nordic-summer-internship', 'en', 'Nordic Summer Internship', 'Three paid months in Oslo with a mentor, a real project and travel support.', 'Twelve interns join a product team each summer, ship one project and present it on demo day.', 'Monthly stipend, shared housing and up to 500 EUR for travel.', 'Apply online with a CV, a short motivation letter and your transcript.'),
  ('demo-nordic-summer-internship', 'uz', 'Nordik yozgi amaliyoti', 'Osloda uch oylik haq toʻlanadigan amaliyot: mentor, real loyiha va yoʻl xarajatlari.', 'Har yozda oʻn ikki amaliyotchi mahsulot jamoasiga qoʻshiladi, bitta loyihani yakunlaydi va demo-kunda taqdim etadi.', 'Oylik stipendiya, umumiy turar joy va 500 yevrogacha yoʻl xarajati.', 'CV, qisqa motivatsion xat va transkript bilan onlayn ariza topshiring.'),
  ('demo-nordic-summer-internship', 'ru', 'Летняя стажировка в Норвегии', 'Три оплачиваемых месяца в Осло: наставник, реальный проект и компенсация дороги.', 'Каждое лето двенадцать стажёров работают в продуктовых командах, завершают один проект и представляют его на демо-дне.', 'Ежемесячная стипендия, общежитие и до 500 евро на дорогу.', 'Подайте заявку онлайн: резюме, короткое мотивационное письмо и транскрипт.'),
  ('demo-tashkent-tech-internship', 'en', 'Tashkent Tech Internship', 'Six-month paid internship at a Tashkent innovation centre; applications are reviewed every two weeks.', 'Interns work with local startups on web and mobile products and receive weekly mentoring.', 'Monthly stipend in UZS and a free co-working desk.', 'Send a CV and a short motivation letter through the online form.'),
  ('demo-tashkent-tech-internship', 'uz', 'Toshkent texnologiya amaliyoti', 'Toshkent innovatsiya markazida olti oylik haq toʻlanadigan amaliyot; arizalar har ikki haftada koʻrib chiqiladi.', 'Amaliyotchilar mahalliy startaplar bilan veb va mobil mahsulotlar ustida ishlaydi, har hafta mentor bilan uchrashadi.', 'UZSda oylik stipendiya va bepul kovorking joyi.', 'CV va qisqa motivatsion xatni onlayn shakl orqali yuboring.'),
  ('demo-tashkent-tech-internship', 'ru', 'Технологическая стажировка в Ташкенте', 'Шестимесячная оплачиваемая стажировка в ташкентском инновационном центре; заявки рассматривают каждые две недели.', 'Стажёры работают с местными стартапами над веб- и мобильными продуктами и каждую неделю встречаются с наставником.', 'Ежемесячная стипендия в UZS и бесплатное место в коворкинге.', 'Отправьте резюме и короткое мотивационное письмо через онлайн-форму.'),
  ('demo-gulf-energy-internship', 'en', 'Gulf Energy Internship', 'Four months in Dubai on a solar project, with a housing stipend.', 'The internship covers site visits, data collection and support for the engineering team.', 'Housing stipend of 1500 AED per month.', 'Apply with a CV, transcript and a copy of your passport.'),
  ('demo-gulf-energy-internship', 'uz', 'Koʻrfaz energetika amaliyoti', 'Dubayda quyosh energiyasi loyihasida toʻrt oylik amaliyot, turar joy uchun stipendiya bilan.', 'Amaliyot obyektga tashriflar, maʼlumot yigʻish va muhandislar jamoasini qoʻllab-quvvatlashni oʻz ichiga oladi.', 'Oyiga 1500 dirham turar joy stipendiyasi.', 'CV, transkript va pasport nusxasi bilan ariza topshiring.'),
  ('demo-gulf-energy-internship', 'ru', 'Стажировка по энергетике в ОАЭ', 'Четыре месяца в Дубае на проекте солнечной энергетики, со стипендией на жильё.', 'Стажировка включает выезды на объект, сбор данных и помощь инженерной команде.', 'Стипендия на жильё 1500 дирхамов в месяц.', 'Подайте резюме, транскрипт и копию паспорта.'),
  ('demo-kyoto-robotics-summer-school', 'en', 'Kyoto Robotics Summer School', 'Two weeks of robotics workshops in Kyoto with full funding and a flight grant.', 'Students build a small robot in teams and test it in the lab at the end of the programme.', 'Tuition, dormitory, meals and a flight grant up to 1200 USD.', 'Apply online with a CV, motivation letter and one recommendation letter.'),
  ('demo-kyoto-robotics-summer-school', 'uz', 'Kioto robototexnika yozgi maktabi', 'Kiotoda ikki haftalik robototexnika mashgʻulotlari: toʻliq moliyalashtirish va yoʻl granti.', 'Talabalar jamoalarda kichik robot yasaydi va dastur oxirida uni laboratoriyada sinovdan oʻtkazadi.', 'Oʻqish, yotoqxona, ovqat va 1200 dollargacha yoʻl granti.', 'CV, motivatsion xat va bitta tavsiyanoma bilan onlayn ariza topshiring.'),
  ('demo-kyoto-robotics-summer-school', 'ru', 'Летняя школа робототехники в Киото', 'Две недели практикумов по робототехнике в Киото: полное финансирование и грант на перелёт.', 'Студенты собирают небольшого робота в командах и тестируют его в лаборатории в конце программы.', 'Обучение, общежитие, питание и грант на перелёт до 1200 USD.', 'Подайте заявку онлайн: резюме, мотивационное письмо и одна рекомендация.'),
  ('demo-warsaw-data-summer-school', 'en', 'Warsaw Data Summer School', 'One intensive week of data analysis in Warsaw; tuition is waived.', 'The week mixes morning lectures with afternoon practice on real, anonymized datasets.', 'Tuition is free; participants cover travel and food.', 'Apply with a CV and a short motivation letter.'),
  ('demo-warsaw-data-summer-school', 'uz', 'Varshava maʼlumotlar yozgi maktabi', 'Varshavada maʼlumotlar tahlili boʻyicha bir haftalik intensiv kurs; oʻqish bepul.', 'Hafta ertalabki maʼruzalar va kunduzgi amaliy mashgʻulotlardan iborat; maʼlumotlar anonimlashtirilgan.', 'Oʻqish bepul; yoʻl va ovqatni qatnashchilar qoplaydi.', 'CV va qisqa motivatsion xat bilan ariza topshiring.'),
  ('demo-warsaw-data-summer-school', 'ru', 'Летняя школа анализа данных в Варшаве', 'Недельный интенсив по анализу данных в Варшаве; обучение бесплатное.', 'Утром лекции, днём практика на реальных обезличенных данных.', 'Обучение бесплатное; дорогу и питание участники оплачивают сами.', 'Подайте резюме и короткое мотивационное письмо.'),
  ('demo-online-sustainability-summer-school', 'en', 'Online Sustainability Summer School', 'A free online week about climate projects for high-school and university students.', 'Daily live sessions and a small group project, all in English.', 'Free participation and a certificate after the final project.', 'Register through the online form and join the welcome session.'),
  ('demo-online-sustainability-summer-school', 'uz', 'Onlayn barqarorlik yozgi maktabi', 'Maktab va universitet talabalari uchun iqlim loyihalari haqida bepul onlayn hafta.', 'Har kuni jonli mashgʻulotlar va kichik guruh loyihasi, barchasi ingliz tilida.', 'Bepul qatnashish va yakuniy loyihadan keyin sertifikat.', 'Onlayn shaklda roʻyxatdan oʻting va kirish darsiga qoʻshiling.'),
  ('demo-online-sustainability-summer-school', 'ru', 'Онлайн-школа устойчивого развития', 'Бесплатная онлайн-неделя о климатических проектах для школьников и студентов.', 'Ежедневные живые занятия и небольшой групповой проект, всё на английском языке.', 'Бесплатное участие и сертификат после итогового проекта.', 'Зарегистрируйтесь через онлайн-форму и подключитесь к вводному занятию.'),
  ('demo-albion-undergraduate-scholarship', 'en', 'Albion Undergraduate Scholarship', 'A full scholarship for a three-year bachelor degree in the United Kingdom.', 'The scholarship covers tuition, accommodation and a monthly living allowance for the whole degree.', 'Tuition, accommodation and 1100 GBP per month.', 'Apply through the university portal with your school transcript and references.'),
  ('demo-albion-undergraduate-scholarship', 'uz', 'Albion bakalavr stipendiyasi', 'Buyuk Britaniyada uch yillik bakalavr dasturi uchun toʻliq stipendiya.', 'Stipendiya butun oʻqish davomida oʻqish haqi, turar joy va oylik nafaqani qoplaydi.', 'Oʻqish haqi, turar joy va oyiga 1100 funt sterling.', 'Universitet portalida maktab transkripti va tavsiyanomalar bilan ariza topshiring.'),
  ('demo-albion-undergraduate-scholarship', 'ru', 'Стипендия Albion для бакалавриата', 'Полная стипендия на трёхлетнюю программу бакалавриата в Великобритании.', 'Стипендия покрывает обучение, проживание и ежемесячное пособие на весь срок учёбы.', 'Обучение, проживание и 1100 фунтов в месяц.', 'Подайте заявку через портал университета со школьным транскриптом и рекомендациями.'),
  ('demo-seoul-bachelor-scholarship', 'en', 'Seoul Bachelor Scholarship', 'Full tuition and a dormitory place for a four-year bachelor degree in Seoul.', 'The programme includes Korean language courses in the first year and a monthly allowance.', 'Full tuition, dormitory and a monthly allowance.', 'Apply online with a transcript, CV and two recommendation letters.'),
  ('demo-seoul-bachelor-scholarship', 'uz', 'Seul bakalavr stipendiyasi', 'Seulda toʻrt yillik bakalavr dasturi uchun toʻliq oʻqish va yotoqxona.', 'Dastur birinchi yilda koreys tili kurslarini va oylik nafaqani oʻz ichiga oladi.', 'Toʻliq oʻqish haqi, yotoqxona va oylik nafaqa.', 'Transkript, CV va ikki tavsiyanoma bilan onlayn ariza topshiring.'),
  ('demo-seoul-bachelor-scholarship', 'ru', 'Стипендия для бакалавриата в Сеуле', 'Полная оплата обучения и место в общежитии на четырёхлетнюю программу в Сеуле.', 'Программа включает курсы корейского языка в первый год и ежемесячное пособие.', 'Полная оплата обучения, общежитие и ежемесячное пособие.', 'Подайте онлайн: транскрипт, резюме и две рекомендации.'),
  ('demo-expired-bachelor-scholarship', 'en', 'Rhein Bachelor Scholarship (closed cycle)', 'Demo listing with a deadline in the past, used to test the expired state.', 'This listing is intentionally expired. Explore hides it by default and the detail page must never look live.', 'Tuition and a monthly stipend for three years.', 'Applications for this cycle are closed.'),
  ('demo-expired-bachelor-scholarship', 'uz', 'Rhein bakalavr stipendiyasi (yopilgan tsikl)', 'Muddati oʻtgan demo eʼlon; eskirgan holatni sinash uchun ishlatiladi.', 'Bu eʼlon ataylab muddati oʻtgan qilib qoʻyilgan. Explore uni standart holatda yashiradi, detal sahifasi esa jonli koʻrinmasligi kerak.', 'Oʻqish haqi va uch yil davomida oylik stipendiya.', 'Bu tsikl uchun arizalar yopilgan.'),
  ('demo-expired-bachelor-scholarship', 'ru', 'Стипендия Rhein для бакалавриата (цикл закрыт)', 'Демо-объявление с прошедшим сроком, нужно для проверки состояния «истекло».', 'Срок специально указан в прошлом. Explore скрывает его по умолчанию, а страница объявления не должна выглядеть активной.', 'Обучение и ежемесячная стипендия на три года.', 'Приём заявок в этом цикле закрыт.'),
  ('demo-nordic-masters-scholarship', 'en', 'Nordic Master Scholarship', 'Two fully funded years in Oslo for a master degree in engineering or computer science.', 'The scholarship covers tuition, housing and a monthly grant, plus a mentor from the industry.', 'Tuition, housing and 1250 EUR per month.', 'Apply online with a CV, motivation letter, transcript and IELTS certificate.'),
  ('demo-nordic-masters-scholarship', 'uz', 'Nordik magistratura stipendiyasi', 'Osloda muhandislik yoki kompyuter fanlari boʻyicha ikki yillik toʻliq moliyalashtirilgan magistratura.', 'Stipendiya oʻqish haqi, turar joy va oylik grantni, shuningdek soha mentorini qoplaydi.', 'Oʻqish haqi, turar joy va oyiga 1250 yevro.', 'CV, motivatsion xat, transkript va IELTS sertifikati bilan onlayn ariza topshiring.'),
  ('demo-nordic-masters-scholarship', 'ru', 'Магистерская стипендия в Норвегии', 'Два года полного финансирования в Осло для магистратуры по инженерии или информатике.', 'Стипендия покрывает обучение, жильё и ежемесячный грант, а также наставника из отрасли.', 'Обучение, жильё и 1250 евро в месяц.', 'Подайте онлайн: резюме, мотивационное письмо, транскрипт и сертификат IELTS.'),
  ('demo-rhein-masters-scholarship', 'en', 'Rhein Master Scholarship', 'A fully funded two-year master degree in Aachen for engineers.', 'The programme combines coursework with a paid research project in the second year.', 'Full tuition and 1000 EUR per month.', 'Apply online with a CV, motivation letter, transcript and references.'),
  ('demo-rhein-masters-scholarship', 'uz', 'Rhein magistratura stipendiyasi', 'Axenda muhandislar uchun ikki yillik toʻliq moliyalashtirilgan magistratura.', 'Dastur oʻquv kurslarini ikkinchi yildagi haq toʻlanadigan ilmiy loyiha bilan birlashtiradi.', 'Toʻliq oʻqish haqi va oyiga 1000 yevro.', 'CV, motivatsion xat, transkript va tavsiyanomalar bilan onlayn ariza topshiring.'),
  ('demo-rhein-masters-scholarship', 'ru', 'Магистерская стипендия Rhein', 'Двухлетняя магистратура с полным финансированием в Ахене для инженеров.', 'Программа сочетает курсы с оплачиваемым исследовательским проектом на втором году.', 'Полная оплата обучения и 1000 евро в месяц.', 'Подайте онлайн: резюме, мотивационное письмо, транскрипт и рекомендации.'),
  ('demo-singapore-masters-scholarship', 'en', 'Singapore Master Scholarship', 'Partial funding for an 18-month master degree in business or finance.', 'Students take courses in Singapore and complete a company project in the final term.', 'Seventy percent of tuition is covered.', 'Apply online with a CV, transcript and motivation letter.'),
  ('demo-singapore-masters-scholarship', 'uz', 'Singapur magistratura stipendiyasi', 'Biznes yoki moliya yoʻnalishida 18 oylik magistratura uchun qisman moliyalashtirish.', 'Talabalar Singapurda oʻqiydi va oxirgi semestrda kompaniya loyihasini yakunlaydi.', 'Oʻqish haqining 70 foizi qoplanadi.', 'CV, transkript va motivatsion xat bilan onlayn ariza topshiring.'),
  ('demo-singapore-masters-scholarship', 'ru', 'Магистерская стипендия в Сингапуре', 'Частичное финансирование 18-месячной магистратуры по бизнесу или финансам.', 'Студенты учатся в Сингапуре и в последнем семестре выполняют проект для компании.', 'Покрывается 70 процентов стоимости обучения.', 'Подайте онлайн: резюме, транскрипт и мотивационное письмо.'),
  ('demo-uzbekistan-government-masters', 'en', 'Uzbekistan Government Master Grant', 'A state grant for Uzbek citizens: tuition plus a monthly allowance.', 'The grant is announced once a year for master programmes at partner universities abroad.', 'Tuition, a monthly allowance and one return flight.', 'Wait for the yearly announcement and apply through the official portal.'),
  ('demo-uzbekistan-government-masters', 'uz', 'Oʻzbekiston davlat magistratura granti', 'Oʻzbekiston fuqarolari uchun davlat granti: oʻqish haqi va oylik nafaqa.', 'Grant har yili chet eldagi hamkor universitetlarda magistratura uchun eʼlon qilinadi.', 'Oʻqish haqi, oylik nafaqa va bitta borish-kelish chiptasi.', 'Yillik eʼlonni kuting va rasmiy portal orqali ariza topshiring.'),
  ('demo-uzbekistan-government-masters', 'ru', 'Государственный грант Узбекистана на магистратуру', 'Государственный грант для граждан Узбекистана: обучение и ежемесячное пособие.', 'Грант объявляют раз в год для магистратуры в зарубежных университетах-партнёрах.', 'Обучение, ежемесячное пособие и один авиабилет туда и обратно.', 'Дождитесь ежегодного объявления и подайте заявку через официальный портал.'),
  ('demo-albion-phd-scholarship', 'en', 'Albion PhD Scholarship', 'Three years of full funding for a PhD in natural sciences or mathematics.', 'Doctoral students join a research group, publish at least one paper and teach one course per year.', 'Fees, 1600 GBP per month and a research budget.', 'Apply online with a research proposal, CV and two references.'),
  ('demo-albion-phd-scholarship', 'uz', 'Albion PhD stipendiyasi', 'Tabiiy fanlar yoki matematika boʻyicha PhD uchun uch yillik toʻliq moliyalashtirish.', 'Doktorantlar ilmiy guruhga qoʻshiladi, kamida bitta maqola chop etadi va yiliga bitta kursdan dars beradi.', 'Oʻqish haqi, oyiga 1600 funt va ilmiy byudjet.', 'Ilmiy taklif, CV va ikki tavsiyanoma bilan onlayn ariza topshiring.'),
  ('demo-albion-phd-scholarship', 'ru', 'Докторская стипендия Albion', 'Три года полного финансирования PhD по естественным наукам или математике.', 'Докторанты работают в исследовательской группе, публикуют минимум одну статью и ведут один курс в год.', 'Обучение, 1600 фунтов в месяц и исследовательский бюджет.', 'Подайте онлайн: научное предложение, резюме и две рекомендации.'),
  ('demo-maple-phd-scholarship', 'en', 'Maple PhD Scholarship', 'Four years of funding in Toronto for a PhD in computer science or engineering.', 'The package includes a research stipend and a teaching assistantship from the second year.', 'Full tuition, 2100 CAD per month and health insurance.', 'Apply online with a research proposal, transcripts and references.'),
  ('demo-maple-phd-scholarship', 'uz', 'Maple PhD stipendiyasi', 'Torontoda kompyuter fanlari yoki muhandislik boʻyicha PhD uchun toʻrt yillik moliyalashtirish.', 'Paket ilmiy stipendiya va ikkinchi yildan boshlab oʻqituvchi yordamchisi ishini oʻz ichiga oladi.', 'Toʻliq oʻqish haqi, oyiga 2100 kanada dollari va tibbiy sugʻurta.', 'Ilmiy taklif, transkriptlar va tavsiyanomalar bilan onlayn ariza topshiring.'),
  ('demo-maple-phd-scholarship', 'ru', 'Докторская стипендия Maple', 'Четыре года финансирования в Торонто для PhD по информатике или инженерии.', 'Пакет включает исследовательскую стипендию и ассистентскую работу со второго года.', 'Полная оплата обучения, 2100 канадских долларов в месяц и медицинская страховка.', 'Подайте онлайн: научное предложение, транскрипты и рекомендации.'),
  ('demo-zurich-phd-positions', 'en', 'Zurich PhD Positions', 'Salaried PhD positions in climate and energy research, open until filled.', 'The lab hires continuously; each position lasts three years and includes conference travel.', 'Salary of 4200 CHF per month and social insurance.', 'Email the lab with a CV and a short research statement, or apply through the portal.'),
  ('demo-zurich-phd-positions', 'uz', 'Tsyurix PhD lavozimlari', 'Iqlim va energetika tadqiqotlari boʻyicha maoshli PhD lavozimlari; joylar toʻlguncha ochiq.', 'Laboratoriya doimiy ravishda ishga qabul qiladi; har bir lavozim uch yil davom etadi va konferensiya xarajatlarini qoplaydi.', 'Oyiga 4200 shveytsariya franki maosh va ijtimoiy sugʻurta.', 'Laboratoriyaga CV va qisqa ilmiy bayonot yuboring yoki portal orqali ariza topshiring.'),
  ('demo-zurich-phd-positions', 'ru', 'Докторские позиции в Цюрихе', 'Оплачиваемые PhD-позиции по климату и энергетике, набор идёт до заполнения.', 'Лаборатория набирает постоянно; позиция рассчитана на три года и включает поездки на конференции.', 'Зарплата 4200 швейцарских франков в месяц и социальная страховка.', 'Напишите в лабораторию с резюме и кратким описанием исследований или подайте заявку через портал.'),
  ('demo-baltic-exchange-semester', 'en', 'Baltic Arts Exchange Semester', 'One semester at an arts academy in Riga with tuition waived.', 'Exchange students take studio courses and present their work in the end-of-term exhibition.', 'Tuition is waived; travel and housing are self-funded.', 'Apply with a CV, portfolio and your current transcript.'),
  ('demo-baltic-exchange-semester', 'uz', 'Boltiqboʻyi sanʼat almashinuvi semestri', 'Rigada sanʼat akademiyasida bir semestr, oʻqish haqi bepul.', 'Almashinuv talabalari studiya kurslarini oʻtaydi va semestr oxiridagi koʻrgazmada ishlarini taqdim etadi.', 'Oʻqish bepul; yoʻl va turar joyni talaba qoplaydi.', 'CV, portfolio va joriy transkript bilan ariza topshiring.'),
  ('demo-baltic-exchange-semester', 'ru', 'Семестр по обмену в Балтийской академии искусств', 'Один семестр в академии искусств в Риге без оплаты обучения.', 'Студенты по обмену посещают студийные курсы и представляют работы на итоговой выставке.', 'Обучение бесплатное; дорогу и жильё студент оплачивает сам.', 'Подайте резюме, портфолио и текущий транскрипт.'),
  ('demo-bosphorus-exchange', 'en', 'Bosphorus Exchange Programme', 'A funded five-month exchange in Istanbul for business and social science students.', 'The grant covers travel, housing and food for the whole semester.', 'Grant of 800 EUR per month.', 'Apply through your home university international office.'),
  ('demo-bosphorus-exchange', 'uz', 'Bosfor almashinuv dasturi', 'Biznes va ijtimoiy fanlar talabalari uchun Istanbulda moliyalashtirilgan besh oylik almashinuv.', 'Grant butun semestr davomida yoʻl, turar joy va ovqatni qoplaydi.', 'Oyiga 800 yevro grant.', 'Oʻz universitetining xalqaro boʻlimi orqali ariza topshiring.'),
  ('demo-bosphorus-exchange', 'ru', 'Программа обмена Босфор', 'Финансируемый пятимесячный обмен в Стамбуле для студентов бизнеса и социальных наук.', 'Грант покрывает дорогу, жильё и питание на весь семестр.', 'Грант 800 евро в месяц.', 'Подайте заявку через международный отдел своего университета.'),
  ('demo-latin-america-exchange', 'en', 'Latin America Exchange Semester', 'A self-funded exchange semester in Santiago; the deadline is announced each year.', 'Students choose courses in humanities and languages and live with a host family.', 'No funding: participants pay tuition and living costs.', 'Contact the international office to be notified when the next call opens.'),
  ('demo-latin-america-exchange', 'uz', 'Lotin Amerikasi almashinuv semestri', 'Santyagoda oʻz hisobidan almashinuv semestri; ariza muddati har yili eʼlon qilinadi.', 'Talabalar gumanitar fanlar va tillar boʻyicha kurslarni tanlaydi va mezbon oilada yashaydi.', 'Moliyalashtirish yoʻq: talaba oʻqish va yashash xarajatlarini qoplaydi.', 'Keyingi qabul qachon ochilishini bilish uchun xalqaro boʻlim bilan bogʻlaning.'),
  ('demo-latin-america-exchange', 'ru', 'Семестр по обмену в Латинской Америке', 'Семестр по обмену в Сантьяго за свой счёт; срок подачи объявляют каждый год.', 'Студенты выбирают курсы по гуманитарным наукам и языкам и живут в принимающей семье.', 'Финансирования нет: студент оплачивает обучение и проживание.', 'Свяжитесь с международным отделом, чтобы узнать о следующем наборе.'),
  ('demo-danube-policy-fellowship', 'en', 'Danube Policy Fellowship', 'A paid 12-month fellowship in Vienna for policy and social science graduates.', 'Fellows work with a policy team, publish one brief per quarter and attend weekly seminars.', 'Monthly stipend of 1800 EUR and a training budget.', 'Apply online with a CV, motivation letter and two references.'),
  ('demo-danube-policy-fellowship', 'uz', 'Dunay siyosat fellowshipi', 'Siyosat va ijtimoiy fanlar bitiruvchilari uchun Vena shahrida 12 oylik haq toʻlanadigan fellowship.', 'Fellows siyosat jamoasi bilan ishlaydi, chorakda bitta brif chop etadi va haftalik seminarlarda qatnashadi.', 'Oyiga 1800 yevro stipendiya va taʼlim byudjeti.', 'CV, motivatsion xat va ikki tavsiyanoma bilan onlayn ariza topshiring.'),
  ('demo-danube-policy-fellowship', 'ru', 'Феллоушип Дуная по политике', 'Оплачиваемый 12-месячный феллоушип в Вене для выпускников по политике и социальным наукам.', 'Феллоу работают с командой по политике, публикуют один бриф в квартал и посещают еженедельные семинары.', 'Стипендия 1800 евро в месяц и бюджет на обучение.', 'Подайте онлайн: резюме, мотивационное письмо и две рекомендации.'),
  ('demo-eu-only-research-fellowship', 'en', 'European Research Fellowship (EU nationals)', 'Eighteen months of funded research in Brussels; only EU nationals may apply.', 'Fellows join a research team working on energy and climate policy and publish two reports.', 'Salary, research costs and travel for 18 months.', 'Apply online with a CV, a research proposal and two references.'),
  ('demo-eu-only-research-fellowship', 'uz', 'Yevropa tadqiqot fellowshipi (Yevropa Ittifoqi fuqarolari)', 'Bryusselda 18 oylik moliyalashtirilgan tadqiqot; faqat Yevropa Ittifoqi fuqarolari ariza topshira oladi.', 'Fellows energetika va iqlim siyosati boʻyicha tadqiqot jamoasiga qoʻshiladi va ikki hisobot chop etadi.', '18 oy davomida maosh, tadqiqot xarajatlari va yoʻl xarajatlari.', 'CV, ilmiy taklif va ikki tavsiyanoma bilan onlayn ariza topshiring.'),
  ('demo-eu-only-research-fellowship', 'ru', 'Европейский исследовательский феллоушип (граждане ЕС)', 'Восемнадцать месяцев финансируемых исследований в Брюсселе; подать заявку могут только граждане ЕС.', 'Феллоу входят в исследовательскую команду по энергетике и климатической политике и публикуют два отчёта.', 'Зарплата, расходы на исследования и поездки на 18 месяцев.', 'Подайте онлайн: резюме, научное предложение и две рекомендации.'),
  ('demo-sahara-development-fellowship', 'en', 'Sahara Development Fellowship', 'Nine months of field work in Nairobi with a monthly stipend.', 'Fellows support rural development projects and report to a local partner organization.', 'Stipend of 900 USD per month and field costs.', 'Apply with a CV, motivation letter and two references.'),
  ('demo-sahara-development-fellowship', 'uz', 'Sahro taraqqiyot fellowshipi', 'Nayrobida toʻqqiz oylik amaliy ish, oylik stipendiya bilan.', 'Fellows qishloq taraqqiyoti loyihalarini qoʻllab-quvvatlaydi va mahalliy hamkor tashkilotga hisobot beradi.', 'Oyiga 900 dollar stipendiya va amaliy xarajatlar.', 'CV, motivatsion xat va ikki tavsiyanoma bilan ariza topshiring.'),
  ('demo-sahara-development-fellowship', 'ru', 'Феллоушип развития Сахары', 'Девять месяцев полевой работы в Найроби с ежемесячной стипендией.', 'Феллоу поддерживают проекты развития сельских районов и отчитываются перед местной партнёрской организацией.', 'Стипендия 900 долларов в месяц и полевые расходы.', 'Подайте резюме, мотивационное письмо и две рекомендации.'),
  ('demo-amazon-field-research', 'en', 'Amazon Field Research Programme', 'Six months at a field station near Manaus; housing and meals are covered.', 'Researchers collect biodiversity data with local guides and publish an open dataset.', 'Field station and meals covered; flights are not included.', 'Apply with a CV, a short research proposal and a passport copy.'),
  ('demo-amazon-field-research', 'uz', 'Amazonka dala tadqiqoti dasturi', 'Manaus yaqinidagi dala stansiyasida olti oy; turar joy va ovqat qoplanadi.', 'Tadqiqotchilar mahalliy yoʻl boshlovchilar bilan biologik xilma-xillik maʼlumotlarini yigʻadi va ochiq maʼlumotlar toʻplamini chop etadi.', 'Dala stansiyasi va ovqat qoplanadi; aviachiptalar kirmaydi.', 'CV, qisqa ilmiy taklif va pasport nusxasi bilan ariza topshiring.'),
  ('demo-amazon-field-research', 'ru', 'Программа полевых исследований в Амазонии', 'Шесть месяцев на полевой станции под Манаусом; жильё и питание оплачиваются.', 'Исследователи собирают данные о биоразнообразии вместе с местными проводниками и публикуют открытый набор данных.', 'Полевая станция и питание оплачиваются; перелёт не входит.', 'Подайте резюме, короткое научное предложение и копию паспорта.'),
  ('demo-pacific-climate-research', 'en', 'Pacific Climate Research Assistantship', 'Twelve months of funded PhD research in San Diego.', 'The assistantship includes tuition, health insurance and work on a coastal climate dataset.', 'Research assistantship with tuition and health insurance, plus 2400 USD per month.', 'Apply through the university portal with a CV, research proposal and references.'),
  ('demo-pacific-climate-research', 'uz', 'Tinch okeani iqlim tadqiqoti assistentligi', 'San-Diyegoda PhD uchun 12 oylik moliyalashtirilgan tadqiqot.', 'Assistentlik oʻqish haqi, tibbiy sugʻurta va qirgʻoq iqlimi maʼlumotlari ustida ishlashni oʻz ichiga oladi.', 'Oʻqish haqi va tibbiy sugʻurta bilan tadqiqot assistentligi, oyiga 2400 dollar.', 'Universitet portali orqali CV, ilmiy taklif va tavsiyanomalar bilan ariza topshiring.'),
  ('demo-pacific-climate-research', 'ru', 'Ассистентская позиция по климату в Сан-Диего', 'Двенадцать месяцев финансируемых PhD-исследований в Сан-Диего.', 'Ассистентство включает обучение, медицинскую страховку и работу с прибрежным климатическим набором данных.', 'Исследовательская ассистентура с оплатой обучения и страховкой, плюс 2400 долларов в месяц.', 'Подайте через портал университета: резюме, научное предложение и рекомендации.'),
  ('demo-youth-climate-grant', 'en', 'Youth Climate Action Grant', 'A 5000 CHF grant for a six-month community climate project in Geneva.', 'The grant covers materials and a small team stipend for one project team.', 'Grant of 5000 CHF for six months.', 'Apply online with a CV and a two-page project idea.'),
  ('demo-youth-climate-grant', 'uz', 'Yoshlar iqlim harakati granti', 'Jenevada olti oylik jamoa iqlim loyihasi uchun 5000 frank grant.', 'Grant bitta loyiha jamoasi uchun materiallar va kichik stipendiyani qoplaydi.', 'Olti oy uchun 5000 shveytsariya franki grant.', 'CV va ikki betlik loyiha gʻoyasi bilan onlayn ariza topshiring.'),
  ('demo-youth-climate-grant', 'ru', 'Грант молодёжных климатических проектов', 'Грант 5000 швейцарских франков на шестимесячный общественный климатический проект в Женеве.', 'Грант покрывает материалы и небольшую стипендию для одной проектной команды.', 'Грант 5000 франков на шесть месяцев.', 'Подайте онлайн: резюме и описание идеи проекта на две страницы.'),
  ('demo-central-asia-startup-grant', 'en', 'Central Asia Startup Grant', 'A 10000 USD seed grant with mentoring for founders from five Central Asian countries.', 'Selected teams receive money, a mentor and office hours with investors for six months.', 'Seed grant of 10000 USD plus mentoring.', 'Apply online with a CV and a short description of your idea or prototype.'),
  ('demo-central-asia-startup-grant', 'uz', 'Markaziy Osiyo startap granti', 'Besh Markaziy Osiyo davlatidan boʻlgan asoschilar uchun 10000 dollar grant va mentorlik.', 'Tanlangan jamoalar olti oy davomida pul, mentor va investorlar bilan uchrashuvlarni oladi.', '10000 dollar grant va mentorlik.', 'CV va gʻoya yoki prototipning qisqa tavsifi bilan onlayn ariza topshiring.'),
  ('demo-central-asia-startup-grant', 'ru', 'Стартап-грант Центральной Азии', 'Посевной грант 10 000 долларов с менторством для основателей из пяти стран Центральной Азии.', 'Отобранные команды в течение шести месяцев получают деньги, ментора и встречи с инвесторами.', 'Посевной грант 10 000 долларов и менторство.', 'Подайте онлайн: резюме и короткое описание идеи или прототипа.'),
  ('demo-community-arts-grant', 'en', 'Community Arts Grant', 'Materials budget and studio space in Cape Town for nine months.', 'Artists work on one community project and show the result in an open studio week.', 'Materials budget, studio space and 1500 USD in total.', 'Apply with a portfolio and a CV; no formal degree is required.'),
  ('demo-community-arts-grant', 'uz', 'Jamoa sanʼati granti', 'Keyptaunda toʻqqiz oy davomida materiallar byudjeti va studiya maydoni.', 'Rassomlar bitta jamoa loyihasi ustida ishlaydi va natijani ochiq studiya haftaligida koʻrsatadi.', 'Materiallar byudjeti, studiya maydoni va jami 1500 dollar.', 'Portfolio va CV bilan ariza topshiring; rasmiy diplom talab qilinmaydi.'),
  ('demo-community-arts-grant', 'ru', 'Грант для общественных искусств', 'Бюджет на материалы и студийное пространство в Кейптауне на девять месяцев.', 'Художники работают над одним общественным проектом и показывают результат на открытой студийной неделе.', 'Бюджет на материалы, студия и 1500 долларов всего.', 'Подайте портфолио и резюме; формальный диплом не требуется.'),
  ('demo-global-math-olympiad', 'en', 'Global Mathematics Olympiad', 'A free online contest for high-school students, held twice a year.', 'The contest has two online rounds; finalists receive a certificate and a mentor session.', 'Free entry and certificates for finalists.', 'Register on the contest website before the deadline.'),
  ('demo-global-math-olympiad', 'uz', 'Global matematika olimpiadasi', 'Maktab oʻquvchilari uchun bepul onlayn musobaqa, yiliga ikki marta oʻtkaziladi.', 'Musobaqa ikki onlayn bosqichdan iborat; finalchilar sertifikat va mentor sessiyasini oladi.', 'Bepul ishtirok va finalchilar uchun sertifikatlar.', 'Muddat tugashidan oldin musobaqa veb-saytida roʻyxatdan oʻting.'),
  ('demo-global-math-olympiad', 'ru', 'Всемирная математическая олимпиада', 'Бесплатный онлайн-конкурс для школьников, проводится дважды в год.', 'Конкурс состоит из двух онлайн-туров; финалисты получают сертификат и занятие с ментором.', 'Бесплатное участие и сертификаты финалистам.', 'Зарегистрируйтесь на сайте конкурса до окончания срока.'),
  ('demo-climate-innovation-competition', 'en', 'Climate Innovation Competition', 'A team contest in Amsterdam with travel support and a cash prize.', 'Teams present a climate solution to a jury; the best three teams share the prize fund.', 'Travel costs for finalists and a cash prize of 3000 EUR for the winner.', 'Apply with a portfolio and a CV; teams of two to five people.'),
  ('demo-climate-innovation-competition', 'uz', 'Iqlim innovatsiyalari musobaqasi', 'Amsterdamda yoʻl xarajatlari va pul mukofoti bilan jamoaviy musobaqa.', 'Jamoalar iqlim yechimini hakamlar hayʼatiga taqdim etadi; eng yaxshi uch jamoa mukofot fondini boʻlishadi.', 'Finalchilar uchun yoʻl xarajatlari va gʻolibga 3000 yevro pul mukofoti.', 'Portfolio va CV bilan ariza topshiring; jamoa ikki-besh kishidan iborat.'),
  ('demo-climate-innovation-competition', 'ru', 'Конкурс климатических инноваций', 'Командный конкурс в Амстердаме с оплатой дороги и денежным призом.', 'Команды представляют климатическое решение жюри; три лучшие команды делят призовой фонд.', 'Оплата дороги финалистам и приз 3000 евро победителю.', 'Подайте портфолио и резюме; команды от двух до пяти человек.'),
  ('demo-robotics-challenge', 'en', 'Busan Robotics Challenge', 'A one-week team challenge; the deadline is only five days away.', 'Teams build a robot for a fixed track and race it in the final round.', 'Travel grant of 700 USD per team for the final round only.', 'Apply with a portfolio and a CV before the deadline.'),
  ('demo-robotics-challenge', 'uz', 'Pusan robototexnika tanlovi', 'Bir haftalik jamoaviy tanlov; ariza muddati besh kundan keyin tugaydi.', 'Jamoalar belgilangan trek uchun robot yasaydi va finalda uni sinovdan oʻtkazadi.', 'Faqat final uchun har bir jamoaga 700 dollar yoʻl granti.', 'Muddat tugashidan oldin portfolio va CV bilan ariza topshiring.'),
  ('demo-robotics-challenge', 'ru', 'Робототехнический челлендж в Пусане', 'Недельный командный челлендж; до окончания приёма заявок пять дней.', 'Команды собирают робота для заданной трассы и соревнуются в финальном раунде.', 'Дорожный грант 700 долларов на команду только для финала.', 'Подайте портфолио и резюме до окончания срока.'),
  ('demo-youth-ai-conference', 'en', 'Youth AI Conference', 'A one-day hybrid conference in Barcelona; the registration fee is waived.', 'Students present short talks and posters about applied machine learning.', 'Registration fee waived; travel is self-funded.', 'Apply with a CV and a short motivation letter.'),
  ('demo-youth-ai-conference', 'uz', 'Yoshlar AI konferensiyasi', 'Barselonada bir kunlik gibrid konferensiya; roʻyxatdan oʻtish toʻlovi olinmaydi.', 'Talabalar amaliy mashinaviy oʻqitish boʻyicha qisqa maʼruzalar va posterlar taqdim etadi.', 'Roʻyxatdan oʻtish bepul; yoʻl xarajatini talaba qoplaydi.', 'CV va qisqa motivatsion xat bilan ariza topshiring.'),
  ('demo-youth-ai-conference', 'ru', 'Молодёжная конференция по ИИ', 'Однодневная гибридная конференция в Барселоне; регистрационный взнос отменён.', 'Студенты представляют короткие доклады и постеры о прикладном машинном обучении.', 'Регистрация бесплатная; дорогу участник оплачивает сам.', 'Подайте резюме и короткое мотивационное письмо.'),
  ('demo-public-health-conference', 'en', 'Cairo Public Health Conference', 'A three-day conference with a discounted fee for accepted speakers.', 'Accepted speakers present research and join workshops on public health communication.', 'Discounted registration for accepted speakers.', 'Submit a short abstract and a CV through the conference portal.'),
  ('demo-public-health-conference', 'uz', 'Qohira jamoat salomatligi konferensiyasi', 'Qabul qilingan maʼruzachilar uchun chegirmali toʻlov bilan uch kunlik konferensiya.', 'Maʼruzachilar tadqiqotlarini taqdim etadi va jamoat salomatligi kommunikatsiyasi boʻyicha seminarlarda qatnashadi.', 'Qabul qilingan maʼruzachilar uchun chegirmali roʻyxatdan oʻtish.', 'Konferensiya portali orqali qisqa annotatsiya va CV yuboring.'),
  ('demo-public-health-conference', 'ru', 'Конференция по общественному здравоохранению в Каире', 'Трёхдневная конференция со скидкой на взнос для принятых докладчиков.', 'Принятые докладчики представляют исследования и участвуют в семинарах по коммуникации в здравоохранении.', 'Скидка на регистрацию для принятых докладчиков.', 'Отправьте короткую аннотацию и резюме через портал конференции.'),
  ('demo-coastal-cleanup-volunteering', 'en', 'Coastal Cleanup Volunteering', 'One week of beach cleanups near Lisbon with free local transport.', 'Volunteers join morning cleanups and an afternoon workshop on plastic waste.', 'Unpaid programme with free local transport.', 'Send a short form with your contact details and availability.'),
  ('demo-coastal-cleanup-volunteering', 'uz', 'Qirgʻoqni tozalash koʻngilliligi', 'Lissabon yaqinida bir haftalik plyaj tozalash, mahalliy transport bepul.', 'Koʻngillilar ertalab tozalash ishlarida, kunduzi plastik chiqindilar boʻyicha seminarda qatnashadi.', 'Haq toʻlanmaydigan dastur, mahalliy transport bepul.', 'Aloqa maʼlumotlari va boʻsh vaqtingizni koʻrsatib qisqa shakl yuboring.'),
  ('demo-coastal-cleanup-volunteering', 'ru', 'Волонтёрство по очистке побережья', 'Неделя уборок пляжей под Лиссабоном с бесплатным местным транспортом.', 'Волонтёры участвуют в утренних уборках и дневном семинаре о пластиковых отходах.', 'Неоплачиваемая программа с бесплатным местным транспортом.', 'Отправьте короткую форму с контактами и доступными датами.'),
  ('demo-online-translation-volunteering', 'en', 'Online Translation Volunteering', 'Remote volunteering, about four hours per week; the start date is flexible.', 'Volunteers translate short texts into Uzbek or Russian for a non-profit website.', 'Remote and unpaid; flexible hours.', 'Send a CV and a short translation sample.'),
  ('demo-online-translation-volunteering', 'uz', 'Onlayn tarjima koʻngilliligi', 'Masofadan koʻngillilik, haftasiga taxminan toʻrt soat; boshlash sanasi moslashuvchan.', 'Koʻngillilar notijorat veb-sayt uchun qisqa matnlarni oʻzbek yoki rus tiliga tarjima qiladi.', 'Masofadan va haq toʻlanmaydi; ish vaqti moslashuvchan.', 'CV va qisqa tarjima namunasini yuboring.'),
  ('demo-online-translation-volunteering', 'ru', 'Онлайн-волонтёрство перевода', 'Удалённое волонтёрство, около четырёх часов в неделю; дата начала гибкая.', 'Волонтёры переводят короткие тексты на узбекский или русский язык для сайта некоммерческой организации.', 'Удалённо и без оплаты; гибкий график.', 'Отправьте резюме и короткий пример перевода.'),
  ('demo-junior-data-analyst-job', 'en', 'Junior Data Analyst', 'A full-time entry-level job in Tashkent with a salary and health insurance.', 'The analyst builds dashboards, cleans data and supports the product team with weekly reports.', 'Full-time salary in UZS and health insurance.', 'Send a CV, a short motivation letter and your transcript.'),
  ('demo-junior-data-analyst-job', 'uz', 'Kichik maʼlumotlar tahlilchisi', 'Toshkentda toʻliq kunlik boshlangʻich ish: maosh va tibbiy sugʻurta.', 'Tahlilchi dashtbordlar yaratadi, maʼlumotlarni tozalaydi va mahsulot jamoasini haftalik hisobotlar bilan qoʻllab-quvvatlaydi.', 'UZSda toʻliq kunlik maosh va tibbiy sugʻurta.', 'CV, qisqa motivatsion xat va transkript yuboring.'),
  ('demo-junior-data-analyst-job', 'ru', 'Младший аналитик данных', 'Полная занятость в Ташкенте: зарплата и медицинская страховка.', 'Аналитик строит дашборды, чистит данные и готовит для продуктовой команды еженедельные отчёты.', 'Полная ставка с зарплатой в UZS и медицинской страховкой.', 'Отправьте резюме, короткое мотивационное письмо и транскрипт.'),
  ('demo-graduate-engineer-program', 'en', 'Graduate Engineer Programme', 'A two-year programme in Dublin with three rotations and a full salary.', 'Graduates rotate between design, site and quality teams and finish with a certification.', 'Salary of 3200 EUR per month for two years.', 'Apply with a CV and transcript through the careers page.'),
  ('demo-graduate-engineer-program', 'uz', 'Bitiruvchi muhandis dasturi', 'Dublinda uch rotatsiyali va toʻliq maoshli ikki yillik dastur.', 'Bitiruvchilar loyihalash, qurilish va sifat jamoalarida rotatsiyadan oʻtadi va oxirida sertifikat oladi.', 'Ikki yil davomida oyiga 3200 yevro maosh.', 'Karyera sahifasi orqali CV va transkript bilan ariza topshiring.'),
  ('demo-graduate-engineer-program', 'ru', 'Программа для выпускников-инженеров', 'Двухлетняя программа в Дублине с тремя ротациями и полной зарплатой.', 'Выпускники проходят ротации в проектировании, на площадке и в отделе качества и получают сертификат.', 'Зарплата 3200 евро в месяц в течение двух лет.', 'Подайте резюме и транскрипт через страницу вакансий.'),
  ('demo-free-python-course', 'en', 'Free Python Course', 'A free self-paced online course with a certificate at the end.', 'Eight short modules cover variables, loops, functions and a small final project.', 'Free access and a certificate after the final project.', 'Create an account on the course platform and start any time.'),
  ('demo-free-python-course', 'uz', 'Bepul Python kursi', 'Bepul onlayn kurs, oxirida sertifikat bilan.', 'Sakkiz qisqa modul oʻzgaruvchilar, sikllar, funksiyalar va kichik yakuniy loyihani qamrab oladi.', 'Bepul kirish va yakuniy loyihadan keyin sertifikat.', 'Kurs platformasida akkaunt yarating va istalgan vaqtda boshlang.'),
  ('demo-free-python-course', 'ru', 'Бесплатный курс Python', 'Бесплатный онлайн-курс в своём темпе с сертификатом в конце.', 'Восемь коротких модулей охватывают переменные, циклы, функции и небольшой итоговый проект.', 'Бесплатный доступ и сертификат после итогового проекта.', 'Создайте аккаунт на платформе курса и начинайте в любое время.'),
  ('demo-german-language-course', 'en', 'German Language Course', 'A four-month German course in Munich; half of the fee is covered.', 'The course runs from A2 to B1 with two evening classes per week and a final test.', 'Half of the course fee is covered by the institute.', 'Register online and take the placement test.'),
  ('demo-german-language-course', 'uz', 'Nemis tili kursi', 'Myunxenda toʻrt oylik nemis tili kursi; toʻlovning yarmi qoplanadi.', 'Kurs A2 dan B1 gacha davom etadi, haftada ikki kechki dars va yakuniy test.', 'Kurs toʻlovining yarmini institut qoplaydi.', 'Onlayn roʻyxatdan oʻting va darajani aniqlash testini topshiring.'),
  ('demo-german-language-course', 'ru', 'Курс немецкого языка', 'Четырёхмесячный курс немецкого в Мюнхене; половина стоимости покрывается.', 'Курс идёт от A2 до B1: два вечерних занятия в неделю и итоговый тест.', 'Половину стоимости курса оплачивает институт.', 'Зарегистрируйтесь онлайн и пройдите тест на уровень.'),
  ('demo-project-management-course', 'en', 'Project Management Course', 'A three-month online course; students pay half of the fee.', 'The course covers planning, risk and stakeholder management with a practical group case.', 'Course fee reduced by 50 percent for students.', 'Register online with a CV and proof of student status.'),
  ('demo-project-management-course', 'uz', 'Loyiha boshqaruvi kursi', 'Uch oylik onlayn kurs; talabalar toʻlovning yarmini toʻlaydi.', 'Kurs rejalashtirish, xatarlar va manfaatdor tomonlar bilan ishlashni amaliy guruh ishi bilan qamrab oladi.', 'Talabalar uchun kurs toʻlovi 50 foizga kamaytirilgan.', 'CV va talabalik maʼlumotnomasi bilan onlayn roʻyxatdan oʻting.'),
  ('demo-project-management-course', 'ru', 'Курс управления проектами', 'Трёхмесячный онлайн-курс; студенты оплачивают половину стоимости.', 'Курс охватывает планирование, риски и работу со стейкхолдерами на практическом групповом кейсе.', 'Стоимость курса снижена на 50 процентов для студентов.', 'Зарегистрируйтесь онлайн с резюме и подтверждением статуса студента.'),
  ('demo-remote-design-internship', 'en', 'Remote Design Internship', 'A three-month remote internship with a small monthly stipend.', 'The intern supports a design team with social media graphics and one longer project.', 'Remote internship with a monthly stipend of 400 EUR.', 'Apply with a portfolio and a CV.'),
  ('demo-remote-design-internship', 'uz', 'Masofaviy dizayn amaliyoti', 'Uch oylik masofaviy amaliyot, kichik oylik stipendiya bilan.', 'Amaliyotchi dizayn jamoasini ijtimoiy tarmoq grafikalari va bitta uzoqroq loyiha bilan qoʻllab-quvvatlaydi.', 'Masofaviy amaliyot, oyiga 400 yevro stipendiya.', 'Portfolio va CV bilan ariza topshiring.'),
  ('demo-remote-design-internship', 'ru', 'Удалённая стажировка дизайнера', 'Трёхмесячная удалённая стажировка с небольшой месячной стипендией.', 'Стажёр помогает дизайн-команде с графикой для соцсетей и одним более длинным проектом.', 'Удалённая стажировка со стипендией 400 евро в месяц.', 'Подайте портфолио и резюме.')
