insert into public.opportunity_translations (
  opportunity_id, locale, title, short_summary, description_md, benefits, how_to_apply
)
select
  o.id,
  tr.locale,
  tr.title,
  tr.short_summary,
  tr.description_md,
  tr.benefits,
  tr.how_to_apply
from tr
join public.opportunities o on o.slug = tr.slug;


